fn diag_val(i: i32, j: i32) -> f64 {
    // Requires: i and j are valid indices for the diagonal check
    // Ensures: Returns 1.0 if i equals j, otherwise returns 0.0
    assert!(i >= 0 && j >= 0); // Assert that i and j are non-negative
    if i == j {
        1.0
    } else {
        0.0
    }
}

fn identity(n: usize) -> Vec<Vec<f64>> {
    // Requires: n is a non-negative integer
    // Ensures: Returns an n x n identity matrix
    // Invariant: For all i, j in the range 0..n, matrix[i][j] is 1.0 if i == j, else 0.0
    let mut matrix = Vec::with_capacity(n);
    
    // Loop invariant: For all k in 0..i, matrix[k] is a valid row of the identity matrix
    for i in 0..n {
        let mut row = Vec::with_capacity(n);
        
        // Loop invariant: For all k in 0..j, row[k] is 1.0 if i == k, else 0.0
        for j in 0..n {
            row.push(diag_val(i as i32, j as i32));
        }
        
        matrix.push(row);
    }
    
    matrix
}

